13	//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
14	type pickerModel struct {
15		allSkills []skilldb.SkillRow // full list before filtering
16		skills    []skilldb.SkillRow // filtered view
17		stats     map[string]*skilldb.SkillStatsResult
18		selected  int
19		scope     int // 0 = all, 1 = repo only, 2 = personal only
20		styles    tuiStyles
21		width     int
22		height    int
23	}
24	
25	func newPickerModel(styles tuiStyles) pickerModel {
26		return pickerModel{
27			styles: styles,
28			stats:  make(map[string]*skilldb.SkillStatsResult),
29		}
30	}
31	
32	func (m *pickerModel) setData(skills []skilldb.SkillRow, stats map[string]*skilldb.SkillStatsResult) {
33		// Deduplicate skills by name — the same skill may be discovered for
34		// multiple source agents (e.g. claude-code and gemini-cli).
35		// Keep one row per name and merge stats across agents.
36		seen := make(map[string]int) // name -> index in deduped
37		var deduped []skilldb.SkillRow
38		merged := make(map[string]*skilldb.SkillStatsResult)
39	
40		for _, skill := range skills {
41			key := skill.Name + "|" + skill.SourceAgent
42			st := stats[key]
43	
44			if idx, ok := seen[skill.Name]; ok {
45				// Merge stats into existing entry.
46				if existing := merged[deduped[idx].Name]; existing != nil && st != nil {
47					existing.TotalSessions += st.TotalSessions
48					existing.TotalFriction += st.TotalFriction
49					existing.TotalTokens += st.TotalTokens
50					if !st.FirstUsed.IsZero() && (existing.FirstUsed.IsZero() || st.FirstUsed.Before(existing.FirstUsed)) {
51						existing.FirstUsed = st.FirstUsed
52					}
53					if st.LastUsed.After(existing.LastUsed) {
54						existing.LastUsed = st.LastUsed
55					}
56					if existing.TotalSessions > 0 {
57						existing.SessionsPerWeek += st.SessionsPerWeek
58						existing.AvgScore = (existing.AvgScore*float64(existing.TotalSessions-st.TotalSessions) +
59							st.AvgScore*float64(st.TotalSessions)) / float64(existing.TotalSessions)
60					}
61				} else if existing == nil && st != nil {
62					merged[deduped[idx].Name] = st
63				}
64				continue
65			}
66	
67			seen[skill.Name] = len(deduped)
68			deduped = append(deduped, skill)
69			if st != nil {
70				cp := *st
71				merged[skill.Name] = &cp
72			}
73		}
74	
75		// Rekey stats by "name|sourceAgent" for the kept rows.
76		m.stats = make(map[string]*skilldb.SkillStatsResult, len(deduped))
77		for _, skill := range deduped {
78			key := skill.Name + "|" + skill.SourceAgent
79			m.stats[key] = merged[skill.Name]
80		}
81	
82		m.allSkills = deduped
83		m.applyFilter()
84	}
85	
86	func (m *pickerModel) applyFilter() {
87		if m.scope == 0 {
88			m.skills = m.allSkills
89		} else {
90			scopeName := skilldb.ScopeRepo
91			if m.scope == 2 {
92				scopeName = skilldb.ScopePersonal
93			}
94			m.skills = nil
95			for _, s := range m.allSkills {
96				if s.Scope == scopeName {
97					m.skills = append(m.skills, s)
98				}
99			}
100		}
101		if m.selected >= len(m.skills) {
102			m.selected = max(0, len(m.skills)-1)
103		}
104	}
105	
106	func (m *pickerModel) setSize(w, h int) { m.width = w; m.height = h }
107	
108	func (m pickerModel) update(msg tea.Msg) (pickerModel, tea.Cmd) {
109		keyMsg, ok := msg.(tea.KeyMsg)
110		if !ok {
111			return m, nil
112		}
113	
114		switch {
115		case key.Matches(keyMsg, pickerKeyMap.Up):
116			if m.selected > 0 {
117				m.selected--
118			}
119		case key.Matches(keyMsg, pickerKeyMap.Down):
120			if m.selected < len(m.skills)-1 {
121				m.selected++
122			}
123		case key.Matches(keyMsg, pickerKeyMap.Filter):
124			m.scope = (m.scope + 1) % 3
125			m.applyFilter()
126		case key.Matches(keyMsg, pickerKeyMap.Enter):
127			if len(m.skills) > 0 {
128				skill := m.skills[m.selected]
129				return m, func() tea.Msg { return skillSelectedMsg{skill: skill} }
130			}
131		}
132	
133		return m, nil
134	}
