239	func (m pickerModel) renderFilterChips() string {
240		labels := [3]string{"All", "Repo", "Personal"}
241		var chips []string
242		for i, label := range labels {
243			if i == m.scope {
244				chips = append(chips, m.styles.render(m.styles.chipActive, "[ "+label+" ]"))
245			} else {
246				chips = append(chips, m.styles.render(m.styles.chipDisabled, "  "+label+"  "))
247			}
248		}
249		return "  " + strings.Join(chips, " ") + "\n"
250	}
251	
252	func formatFrequency(s tuiStyles, perWeek float64) string {
253		rate := fmt.Sprintf("%.1f/wk", perWeek)
254		switch {
255		case perWeek > 1.0:
256			return s.render(s.success, "\u25b2") + " " + rate
257		case perWeek < 0.5:
258			return s.render(s.friction, "\u25bc") + " " + rate
259		default:
260			return s.render(s.dim, "\u2500") + " " + rate
261		}
262	}
