19	// cacheVersion is bumped when matching logic changes to force cache invalidation.
20	// v2: added ResolveSkillName fuzzy matching for LLM-extracted signal names.
21	// v3: attribute Skill tool sessions by reading committed transcripts when skill_signals are absent.
22	// v4: carry friction from skill_signals into transcript-attributed sessions (Step 2).
23	// v5: discover plugin skills from ~/.claude/plugins/cache/.
24	const cacheVersion = "v5"
25	
26	// resolveSkillName matches an LLM-extracted skill signal name to a discovered skill.
27	// LLM-extracted names often differ from canonical names (e.g. "e2e:triage" for skill "e2e",
28	// "superpowers:writing-plans" for "writing-plans", "cli-e2e-failure-fix" for "e2e").
29	//
30	// Match priority:
31	//  1. Exact match
32	//  2. Signal is a sub-skill: "parent:child" where parent matches a discovered skill
33	//  3. Last segment match: "prefix:name" where name matches a discovered skill
34	//  4. Discovered skill name is contained in the signal name as a word boundary
35	func ResolveSkillName(signalName string, skillMap map[string]SkillRow) (SkillRow, bool) {
36		// 1. Exact match.
37		if skill, ok := skillMap[signalName]; ok {
38			return skill, true
39		}
40	
41		// 2. Sub-skill: signal "e2e:triage" matches discovered "e2e".
42		if idx := strings.IndexByte(signalName, ':'); idx > 0 {
43			parent := signalName[:idx]
44			if skill, ok := skillMap[parent]; ok {
45				return skill, true
46			}
47		}
48	
49		// 3. Last segment: signal "superpowers:writing-plans" matches discovered "writing-plans".
50		if idx := strings.LastIndexByte(signalName, ':'); idx >= 0 && idx < len(signalName)-1 {
51			lastSeg := signalName[idx+1:]
52			if skill, ok := skillMap[lastSeg]; ok {
53				return skill, true
54			}
55		}
56	
57		// 4. Discovered skill name appears as a delimited segment in the signal.
58		// E.g. signal "cli-e2e-failure-fix" contains discovered skill "e2e".
59		// We check word boundaries using "-" and ":" as delimiters.
60		for name, skill := range skillMap {
61			if len(name) < 2 {
62				continue // skip very short names to avoid false positives
63			}
64			// Check if name appears bounded by delimiters or string edges.
65			searchIn := signalName
66			for {
67				idx := strings.Index(searchIn, name)
68				if idx < 0 {
69					break
70				}
71				leftOK := idx == 0 || searchIn[idx-1] == '-' || searchIn[idx-1] == ':'
72				rightEnd := idx + len(name)
73				rightOK := rightEnd == len(searchIn) || searchIn[rightEnd] == '-' || searchIn[rightEnd] == ':'
74				if leftOK && rightOK {
75					return skill, true
76				}
77				searchIn = searchIn[idx+1:]
78			}
79		}
80	
81		return SkillRow{}, false
82	}
83	
84	const (
85		outcomeSuccess  = "success"
86		outcomeFriction = "friction"
87	)
88	
89	// PopulateFromInsightsDB populates the skill analytics DB from insightsdb data.
90	// It queries skill_signals and tool_calls to find sessions that used discovered skills.
91	func (sdb *SkillDB) PopulateFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) error {
92		if len(discoveredSkills) == 0 {
93			return nil
94		}
95	
96		// Collect skill names for querying.
97		skillNames := make([]string, len(discoveredSkills))
98		skillMap := make(map[string]SkillRow, len(discoveredSkills))
99		for i, s := range discoveredSkills {
100			skillNames[i] = s.Name
101			skillMap[s.Name] = s
102		}
103	
104		tx, err := sdb.BeginTx(ctx)
105		if err != nil {
106			return fmt.Errorf("begin transaction: %w", err)
107		}
108		defer func() {
109			if err != nil {
110				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
111			}
112		}()
113	
114		// Track which sessions we've already inserted to avoid duplicates.
115		type sessionKey struct {
116			skillName    string
117			checkpointID string
118			sessionIndex int
119		}
120		inserted := make(map[sessionKey]bool)
121	
122		// Step 1: From skill_signals — sessions with friction for specific skills.
123		// Fetch all signals and resolve names in Go, since LLM-extracted names
124		// often differ from canonical discovered names.
125		signals, err := idb.QueryAllSkillSignals(ctx)
126		if err != nil {
127			return fmt.Errorf("query skill signals: %w", err)
128		}
129	
130		for _, sig := range signals {
131			skill, ok := ResolveSkillName(sig.SkillName, skillMap)
132			if !ok {
133				logging.Debug(ctx, "skill signal name not matched to any discovered skill",
134					"signal_name", sig.SkillName)
135				continue
136			}
137	
138			key := sessionKey{skill.Name, sig.CheckpointID, sig.SessionIndex}
139			if inserted[key] {
140				continue
141			}
142			inserted[key] = true
143	
144			frictionCount := len(sig.Friction)
145			outcome := outcomeSuccess
146			if frictionCount > 0 {
147				outcome = outcomeFriction
148			}
149	
150			if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
151				SkillName:     skill.Name,
152				SourceAgent:   skill.SourceAgent,
153				CheckpointID:  sig.CheckpointID,
154				SessionIndex:  sig.SessionIndex,
155				SessionID:     sig.SessionID,
156				Agent:         sig.Agent,
157				Model:         sig.Model,
158				Branch:        sig.Branch,
159				CreatedAt:     sig.CreatedAt,
160				TotalTokens:   sig.TotalTokens,
161				TurnCount:     sig.TurnCount,
162				OverallScore:  sig.OverallScore,
163				FrictionCount: frictionCount,
164				Outcome:       outcome,
165			}); err != nil {
166				return fmt.Errorf("insert skill session: %w", err)
167			}
168	
169			// Insert friction items.
170			for _, f := range sig.Friction {
171				if err = sdb.InsertFrictionTx(ctx, tx,
172					skill.Name, skill.SourceAgent,
173					sig.CheckpointID, sig.SessionIndex,
174					f, "",
175				); err != nil {
176					return fmt.Errorf("insert skill friction: %w", err)
177				}
178			}
179	
180			// Insert missing instruction if present.
181			if sig.MissingInstruction != "" {
182				evidence := strings.Join(sig.Friction, "\n")
183				if err = sdb.InsertMissingInstructionTx(ctx, tx,
184					skill.Name, skill.SourceAgent,
185					sig.CheckpointID, sig.SessionIndex,
186					sig.MissingInstruction, evidence,
187				); err != nil {
188					return fmt.Errorf("insert missing instruction: %w", err)
189				}
190			}
191		}
192	
193		// Build a friction lookup from skill_signals, keyed by (checkpoint_id, session_index).
194		// Step 2 uses this to carry friction into transcript-attributed sessions whose
195		// LLM-extracted skill names didn't resolve in Step 1.
196		type signalKey struct {
197			checkpointID string
198			sessionIndex int
199		}
200		signalsBySession := make(map[signalKey]insightsdb.SkillSignalRow, len(signals))
201		for _, sig := range signals {
202			sk := signalKey{sig.CheckpointID, sig.SessionIndex}
203			// Prefer the signal with friction data if multiple exist for the same session.
204			if existing, ok := signalsBySession[sk]; !ok || len(existing.Friction) == 0 {
205				signalsBySession[sk] = sig
206			}
207		}
208	
209		// Step 2: From tool_calls — sessions that used the Skill tool (friction-free uses).
210		toolSessions, err := idb.QuerySkillToolCallSessions(ctx)
211		if err != nil {
212			return fmt.Errorf("query skill tool call sessions: %w", err)
213		}
214	
215		var store *checkpoint.GitStore
216		getStore := func() (*checkpoint.GitStore, error) {
217			if store != nil {
218				return store, nil
219			}
220			repo, openErr := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
221			if openErr != nil {
222				return nil, fmt.Errorf("open repository for transcript fallback: %w", openErr)
223			}
224			store = checkpoint.NewGitStore(repo)
225			return store, nil
226		}
227	
228		for _, ts := range toolSessions {
229			var matchedTranscriptSkill bool
230	
231			cpID, cpErr := id.NewCheckpointID(ts.CheckpointID)
232			if cpErr == nil {
233				store, storeErr := getStore()
234				if storeErr != nil {
235					return storeErr
236				}
237	
238				content, readErr := store.ReadSessionContent(ctx, cpID, ts.SessionIndex)
239				if readErr == nil && content != nil && len(content.Transcript) > 0 {
240					invokedSkills, extractErr := extractSkillInvocationsFromTranscript(content.Transcript)
241					if extractErr != nil {
242						return fmt.Errorf("extract skill invocations from transcript for %s/%d: %w",
243							ts.CheckpointID, ts.SessionIndex, extractErr)
244					}
245	
246					for _, invokedSkill := range invokedSkills {
247						skill, ok := ResolveSkillName(invokedSkill, skillMap)
248						if !ok {
249							continue
250						}
251	
252						key := sessionKey{skill.Name, ts.CheckpointID, ts.SessionIndex}
253						if inserted[key] {
254							continue
255						}
256						inserted[key] = true
257						matchedTranscriptSkill = true
258	
259						// Look up friction from skill_signals for this session.
260						sk := signalKey{ts.CheckpointID, ts.SessionIndex}
261						sig, hasFriction := signalsBySession[sk]
262						frictionCount := 0
263						outcome := outcomeSuccess
264						if hasFriction && len(sig.Friction) > 0 {
265							frictionCount = len(sig.Friction)
266							outcome = outcomeFriction
267						}
268	
269						if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
270							SkillName:     skill.Name,
271							SourceAgent:   skill.SourceAgent,
272							CheckpointID:  ts.CheckpointID,
273							SessionIndex:  ts.SessionIndex,
274							SessionID:     ts.SessionID,
275							Agent:         ts.Agent,
276							Model:         ts.Model,
277							Branch:        ts.Branch,
278							CreatedAt:     ts.CreatedAt,
279							TotalTokens:   ts.TotalTokens,
280							TurnCount:     ts.TurnCount,
281							OverallScore:  ts.OverallScore,
282							FrictionCount: frictionCount,
283							Outcome:       outcome,
284						}); err != nil {
285							return fmt.Errorf("insert transcript-attributed skill session: %w", err)
286						}
287	
288						if hasFriction {
289							for _, f := range sig.Friction {
290								if err = sdb.InsertFrictionTx(ctx, tx,
291									skill.Name, skill.SourceAgent,
292									ts.CheckpointID, ts.SessionIndex,
293									f, "",
294								); err != nil {
295									return fmt.Errorf("insert transcript-attributed skill friction: %w", err)
296								}
297							}
298							if sig.MissingInstruction != "" {
299								evidence := strings.Join(sig.Friction, "\n")
300								if err = sdb.InsertMissingInstructionTx(ctx, tx,
301									skill.Name, skill.SourceAgent,
302									ts.CheckpointID, ts.SessionIndex,
303									sig.MissingInstruction, evidence,
304								); err != nil {
305									return fmt.Errorf("insert transcript-attributed missing instruction: %w", err)
306								}
307							}
308						}
309					}
310				}
311			}
312	
313			if matchedTranscriptSkill {
314				continue
315			}
316	
317			// We can't determine which specific skill was used from tool_calls alone,
318			// so we skip sessions already covered by skill_signals.
319			// These sessions indicate the Skill tool was invoked but we only record
320			// them if there's exactly one discovered skill (unambiguous attribution).
321			if len(discoveredSkills) == 1 {
322				skill := discoveredSkills[0]
323				key := sessionKey{skill.Name, ts.CheckpointID, ts.SessionIndex}
324				if inserted[key] {
325					continue
326				}
327				inserted[key] = true
328	
329				// Look up friction from skill_signals for this session.
330				sk := signalKey{ts.CheckpointID, ts.SessionIndex}
331				sig, hasFriction := signalsBySession[sk]
332				frictionCount := 0
333				outcome := outcomeSuccess
334				if hasFriction && len(sig.Friction) > 0 {
335					frictionCount = len(sig.Friction)
336					outcome = outcomeFriction
337				}
338	
339				if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
340					SkillName:     skill.Name,
341					SourceAgent:   skill.SourceAgent,
342					CheckpointID:  ts.CheckpointID,
343					SessionIndex:  ts.SessionIndex,
344					SessionID:     ts.SessionID,
345					Agent:         ts.Agent,
346					Model:         ts.Model,
