388	// RefreshFromInsightsDB checks if the cache is stale and repopulates if needed.
389	// Returns true if the cache was refreshed.
390	func (sdb *SkillDB) RefreshFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) (bool, error) {
391		// Check insightsdb branch tip with cache version prefix.
392		// Bumping cacheVersion forces re-population even if the branch tip hasn't changed,
393		// e.g. after fixing the skill name matching logic.
394		currentTip, err := idb.GetBranchTip(ctx)
395		if err != nil {
396			return false, fmt.Errorf("get insightsdb branch tip: %w", err)
397		}
398	
399		versionedTip := cacheVersion + ":" + currentTip
400	
401		cachedTip, err := sdb.GetCacheTip(ctx)
402		if err != nil {
403			return false, fmt.Errorf("get skilldb cache tip: %w", err)
404		}
405	
406		if versionedTip != "" && versionedTip == cachedTip {
407			return false, nil
408		}
409	
410		// Upsert discovered skills.
411		now := time.Now().UTC()
412		for _, skill := range discoveredSkills {
413			if err = sdb.UpsertSkill(ctx, SkillRow{
414				Name:         skill.Name,
415				SourceAgent:  skill.SourceAgent,
416				Path:         skill.Path,
417				Kind:         skill.Kind,
418				DiscoveredAt: now,
419				LastSeenAt:   now,
420			}); err != nil {
421				return false, fmt.Errorf("upsert skill %q: %w", skill.Name, err)
422			}
423		}
424	
425		// Clear existing session data before repopulating.
426		if err = sdb.clearSessionData(ctx); err != nil {
427			return false, fmt.Errorf("clear session data: %w", err)
428		}
429	
430		// Populate from insightsdb.
431		if err = sdb.PopulateFromInsightsDB(ctx, idb, discoveredSkills, repoRoot); err != nil {
432			return false, fmt.Errorf("populate from insightsdb: %w", err)
433		}
434	
435		// Update cache tip with version prefix.
436		if versionedTip != "" {
437			if err = sdb.SetCacheTip(ctx, versionedTip); err != nil {
438				return false, fmt.Errorf("set cache tip: %w", err)
439			}
440		}
441	
442		return true, nil
443	}
