445	// clearSessionData removes all rows from session-related tables.
446	func (sdb *SkillDB) clearSessionData(ctx context.Context) error {
447		tables := []string{"skill_sessions", "skill_friction", "skill_missing_instructions"}
448		for _, table := range tables {
449			if _, err := sdb.db.ExecContext(ctx, "DELETE FROM "+table); err != nil { //nolint:gosec // table names are hardcoded
450				return fmt.Errorf("clear %s: %w", table, err)
451			}
452		}
453		return nil
454	}
