456	func extractSkillInvocationsFromTranscript(content []byte) ([]string, error) {
457		lines, err := transcript.ParseFromBytes(content)
458		if err != nil {
459			return nil, fmt.Errorf("parse transcript: %w", err)
460		}
461	
462		seen := make(map[string]bool)
463		var skills []string
464	
465		for _, line := range lines {
466			if line.Type != transcript.TypeAssistant {
467				continue
468			}
469	
470			var msg transcript.AssistantMessage
471			if err := json.Unmarshal(line.Message, &msg); err != nil {
472				continue
473			}
474	
475			for _, block := range msg.Content {
476				if block.Type != transcript.ContentTypeToolUse || block.Name != "Skill" {
477					continue
478				}
479	
480				var input transcript.ToolInput
481				if err := json.Unmarshal(block.Input, &input); err != nil {
482					continue
483				}
484	
485				skill := strings.TrimSpace(input.Skill)
486				if skill == "" || seen[skill] {
487					continue
488				}
489	
490				seen[skill] = true
491				skills = append(skills, skill)
492			}
493		}
494	
495		return skills, nil
496	}
