27	// DiscoverSkills scans both the repo root and user home for skill files.
28	// Missing directories are silently skipped.
29	func DiscoverSkills(repoRoot string) ([]DiscoveredSkill, error) {
30		homeDir, err := os.UserHomeDir()
31		if err != nil {
32			homeDir = "" // skip personal skills if home dir unavailable
33		}
34	
35		var skills []DiscoveredSkill
36	
37		// Repo skills
38		repoSkills, err := discoverSkillsIn(repoRoot, repoRoot, ScopeRepo)
39		if err != nil {
40			return nil, fmt.Errorf("repo skills: %w", err)
41		}
42		skills = append(skills, repoSkills...)
43	
44		// Personal skills (from ~/.claude/, ~/.gemini/)
45		if homeDir != "" {
46			personalSkills, pErr := discoverSkillsIn(homeDir, homeDir, ScopePersonal)
47			if pErr != nil {
48				return nil, fmt.Errorf("personal skills: %w", pErr)
49			}
50			// Deduplicate: skip personal skills that have the same name+agent as a repo skill.
51			repoNames := make(map[string]bool, len(repoSkills))
52			for _, s := range repoSkills {
53				repoNames[s.Name+"|"+s.SourceAgent] = true
54			}
55			for _, s := range personalSkills {
56				if !repoNames[s.Name+"|"+s.SourceAgent] {
57					skills = append(skills, s)
58				}
59			}
60		}
61	
62		// Plugin skills (from ~/.claude/plugins/cache/).
63		if homeDir != "" {
64			pluginCacheDir := filepath.Join(homeDir, ".claude", "plugins", "cache")
65			pluginSkills := discoverPluginSkills(pluginCacheDir)
66			// Deduplicate: skip plugin skills that overlap with repo or personal skills.
67			existingNames := make(map[string]bool, len(skills))
68			for _, s := range skills {
69				existingNames[s.Name+"|"+s.SourceAgent] = true
70			}
71			for _, s := range pluginSkills {
72				if !existingNames[s.Name+"|"+s.SourceAgent] {
73					skills = append(skills, s)
74					existingNames[s.Name+"|"+s.SourceAgent] = true
75				}
76			}
77		}
78	
79		sort.Slice(skills, func(i, j int) bool {
80			// Repo skills first, then personal, then plugin.
81			if skills[i].Scope != skills[j].Scope {
82				return skills[i].Scope < skills[j].Scope
83			}
84			if skills[i].SourceAgent != skills[j].SourceAgent {
85				return skills[i].SourceAgent < skills[j].SourceAgent
86			}
87			return skills[i].Name < skills[j].Name
88		})
89	
90		return skills, nil
91	}
