93	func discoverSkillsIn(baseDir, relBase, scope string) ([]DiscoveredSkill, error) {
94		var skills []DiscoveredSkill
95	
96		collectors := []struct {
97			pattern     string
98			sourceAgent string
99			kind        string
100			nameFunc    func(match string) string
101			readContent bool
102		}{
103			{
104				pattern:     filepath.Join(baseDir, ".claude", "skills", "*", "SKILL.md"),
105				sourceAgent: "claude-code",
106				kind:        "skill",
107				nameFunc:    func(match string) string { return filepath.Base(filepath.Dir(match)) },
108			},
109			{
110				pattern:     filepath.Join(baseDir, ".claude", "commands", "*.md"),
111				sourceAgent: "claude-code",
112				kind:        "command",
113				nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
114			},
115			{
116				pattern:     filepath.Join(baseDir, ".gemini", "agents", "*.md"),
117				sourceAgent: "gemini-cli",
118				kind:        "agent-def",
119				readContent: true,
120				nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
121			},
122			{
123				pattern:     filepath.Join(baseDir, ".gemini", "commands", "*.md"),
124				sourceAgent: "gemini-cli",
125				kind:        "command",
126				readContent: true,
127				nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
128			},
129		}
130	
131		for _, c := range collectors {
132			matches, err := filepath.Glob(c.pattern)
133			if err != nil {
134				return nil, fmt.Errorf("globbing %s: %w", c.pattern, err)
135			}
136	
137			for _, match := range matches {
138				name := c.nameFunc(match)
139	
140				if c.readContent {
141					content, err := os.ReadFile(match) //nolint:gosec // match comes from filepath.Glob, not user input
142					if err != nil {
143						return nil, fmt.Errorf("reading %s: %w", match, err)
144					}
145					if yamlName := extractYAMLName(string(content)); yamlName != "" {
146						name = yamlName
147					}
148				}
149	
150				relPath, err := filepath.Rel(relBase, match)
151				if err != nil {
152					return nil, fmt.Errorf("computing relative path for %s: %w", match, err)
153				}
154	
155				skills = append(skills, DiscoveredSkill{
156					Name:        name,
157					SourceAgent: c.sourceAgent,
158					Path:        relPath,
159					Kind:        c.kind,
160					Scope:       scope,
161				})
162			}
163		}
164	
165		return skills, nil
166	}
