168	// discoverPluginSkills scans the Claude plugin cache for skills and commands.
169	// Directory structure: {cacheDir}/{org}/{plugin-name}/{version}/skills/*/SKILL.md
170	// For each plugin, the latest version directory (by sort order) is used.
171	// Missing or unreadable directories are silently skipped.
172	func discoverPluginSkills(cacheDir string) []DiscoveredSkill {
173		if _, err := os.Stat(cacheDir); os.IsNotExist(err) {
174			return nil
175		}
176	
177		var skills []DiscoveredSkill
178	
179		orgs, err := os.ReadDir(cacheDir)
180		if err != nil {
181			return nil
182		}
183	
184		for _, org := range orgs {
185			if !org.IsDir() {
186				continue
187			}
188			orgDir := filepath.Join(cacheDir, org.Name())
189			plugins, err := os.ReadDir(orgDir)
190			if err != nil {
191				continue
192			}
193	
194			for _, plugin := range plugins {
195				if !plugin.IsDir() {
196					continue
197				}
198				pluginDir := filepath.Join(orgDir, plugin.Name())
199				latestDir := latestVersionDir(pluginDir)
200				if latestDir == "" {
201					continue
202				}
203	
204				skills = append(skills, discoverInPluginVersion(latestDir)...)
205			}
206		}
207	
208		return skills
209	}
