211	// latestVersionDir returns the path of the latest version subdirectory.
212	func latestVersionDir(pluginDir string) string {
213		entries, err := os.ReadDir(pluginDir)
214		if err != nil {
215			return ""
216		}
217	
218		var latest string
219		for _, e := range entries {
220			if e.IsDir() {
221				latest = e.Name() // relies on ReadDir returning sorted order
222			}
223		}
224		if latest == "" {
225			return ""
226		}
227		return filepath.Join(pluginDir, latest)
228	}
