286	func extractYAMLName(content string) string {
287		lines := strings.Split(content, "\n")
288		if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
289			return ""
290		}
291	
292		for _, line := range lines[1:] {
293			trimmed := strings.TrimSpace(line)
294			if trimmed == "---" {
295				break
296			}
297			if strings.HasPrefix(trimmed, "name:") {
298				value := strings.TrimPrefix(trimmed, "name:")
299				return strings.TrimSpace(value)
300			}
301		}
302	
303		return ""
304	}
