235	func insertFacets(ctx context.Context, tx *sql.Tx, row SessionRow) error {
236		for _, instruction := range row.Facets.RepeatedUserInstructions {
237			if _, err := tx.ExecContext(ctx,
238				`INSERT INTO repeated_user_instructions (checkpoint_id, session_index, instruction, evidence)
239				 VALUES (?, ?, ?, ?)`,
240				row.CheckpointID, row.SessionIndex, instruction.Instruction, joinEvidence(instruction.Evidence),
241			); err != nil {
242				return fmt.Errorf("insert repeated_user_instructions: %w", err)
243			}
244		}
245		for _, signal := range row.Facets.MissingContext {
246			if _, err := tx.ExecContext(ctx,
247				`INSERT INTO missing_context_signals (checkpoint_id, session_index, item, evidence)
248				 VALUES (?, ?, ?, ?)`,
249				row.CheckpointID, row.SessionIndex, signal.Item, joinEvidence(signal.Evidence),
250			); err != nil {
251				return fmt.Errorf("insert missing_context_signals: %w", err)
252			}
253		}
254		for _, loop := range row.Facets.FailureLoops {
255			if _, err := tx.ExecContext(ctx,
256				`INSERT INTO failure_loops (checkpoint_id, session_index, description, count, evidence)
257				 VALUES (?, ?, ?, ?, ?)`,
258				row.CheckpointID, row.SessionIndex, loop.Description, loop.Count, joinEvidence(loop.Evidence),
259			); err != nil {
260				return fmt.Errorf("insert failure_loops: %w", err)
261			}
262		}
263		for _, signal := range row.Facets.SkillSignals {
264			if _, err := tx.ExecContext(ctx,
265				`INSERT INTO skill_signals (checkpoint_id, session_index, skill_name, skill_path, friction, missing_instruction)
266				 VALUES (?, ?, ?, ?, ?, ?)`,
267				row.CheckpointID, row.SessionIndex, signal.SkillName, nullableString(signal.SkillPath),
268				joinEvidence(signal.Friction), nullableString(signal.MissingInstruction),
269			); err != nil {
270				return fmt.Errorf("insert skill_signals: %w", err)
271			}
272		}
273		return nil
274	}
