276	// UpdateSessionSummary updates an existing session row with summary-derived data
277	// (intent, outcome, scores, friction, learnings) and sets has_summary = 1.
278	func (idb *InsightsDB) UpdateSessionSummary(ctx context.Context, row SessionRow) error {
279		tx, err := idb.db.BeginTx(ctx, nil)
280		if err != nil {
281			return fmt.Errorf("begin transaction: %w", err)
282		}
283		defer func() {
284			if err != nil {
285				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
286			}
287		}()
288	
289		_, err = tx.ExecContext(ctx, `
290			UPDATE sessions SET
291				intent = ?, outcome = ?,
292				overall_score = ?, score_token_efficiency = ?, score_first_pass = ?,
293				score_friction = ?, score_focus = ?, has_summary = 1
294			WHERE checkpoint_id = ? AND session_index = ?`,
295			nullableString(row.Intent), nullableString(row.Outcome),
296			row.OverallScore, row.ScoreTokenEff, row.ScoreFirstPass,
297			row.ScoreFriction, row.ScoreFocus,
298			row.CheckpointID, row.SessionIndex,
299		)
300		if err != nil {
301			return fmt.Errorf("update session summary: %w", err)
302		}
303	
304		// Delete old friction/learnings and re-insert.
305		for _, table := range []string{"friction", "learnings"} {
306			if _, err = tx.ExecContext(ctx,
307				"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
308				row.CheckpointID, row.SessionIndex,
309			); err != nil {
310				return fmt.Errorf("delete old %s: %w", table, err)
311			}
312		}
313	
314		if err = insertFriction(ctx, tx, row); err != nil {
315			return err
316		}
317		if err = insertLearnings(ctx, tx, row); err != nil {
318			return err
319		}
320	
321		if err = tx.Commit(); err != nil {
322			return fmt.Errorf("commit transaction: %w", err)
323		}
324		return nil
325	}
