328	func (idb *InsightsDB) UpdateSessionFacets(ctx context.Context, row SessionRow) error {
329		tx, err := idb.db.BeginTx(ctx, nil)
330		if err != nil {
331			return fmt.Errorf("begin transaction: %w", err)
332		}
333		defer func() {
334			if err != nil {
335				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
336			}
337		}()
338	
339		if _, err = tx.ExecContext(ctx, `
340			UPDATE sessions SET has_facets = 1
