354				"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
355				row.CheckpointID, row.SessionIndex,
356			); err != nil {
357				return fmt.Errorf("delete old %s: %w", table, err)
358			}
359		}
360	
361		if err = insertFacets(ctx, tx, row); err != nil {
362			return err
363		}
364	
365		if err = tx.Commit(); err != nil {
366			return fmt.Errorf("commit transaction: %w", err)
367		}
368		return nil
369	}
